// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {GameItems} from "../src/GameItems.sol";

contract InvMutTest is Test {
    GameItems c;

    function setUp() public { c = new GameItems(address(this), address(this)); }

    function testFuzz_property(address actor, uint256 tokenId) public {
        // keep the domain admissible: balanceOf reverts for the zero address
        vm.assume(actor != address(0));

        // No tokens of `tokenId` have ever been created or transferred to `actor`:
        // no game item exists (createGameItem never called), the internal _mint is
        // unreachable, and burn only decreases balances. The ERC1155 invariant that
        // balanceOf reports the actual stored balance therefore requires
        // balanceOf(actor, tokenId) == 0 for every such (actor, tokenId).
        // The mutant returns stored + 1, i.e. 1 instead of 0, for ANY input here.
        assertTrue(c.balanceOf(actor, tokenId) == 0);
    }
}
